          <div className="relative shrink-0 size-[16px]" data-node-id="3092:25162" data-name="trailing-icon">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgTrailingIcon2} />
          </div>
        ))}
      {size === "lg" &&
        !selected &&
        ["hovered", "pressed"].includes(state) &&
        trailingIcon &&
        (trailingIconSwap || (
          <div className="relative shrink-0 size-[16px]" data-node-id="3092:25239" data-name="trailing-icon">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgTrailingIcon1} />
          </div>
        ))}
      {isLgAndDisabled && count && (
        <div className="bg-[var(--color\/element\/disabled,#eee)] content-stretch flex h-[20px] items-center justify-center min-w-[20px] overflow-clip px-[5px] relative rounded-[var(--radius\/full,9999px)] shrink-0" data-node-id="3092:25270" data-name="count">
          <p className="[word-break:break-word] font-['Inter:Semi_Bold'] font-semibold leading-[20px] not-italic relative shrink-0 text-[12px] text-[color:var(--color\/text\/disabled,#aaa)] whitespace-nowrap" data-node-id="3092:25271">
            {countLabel}
          </p>
        </div>
      )}
      {isLgAndDisabled &&
        trailingIcon &&
        (trailingIconSwap || (
          <div className="relative shrink-0 size-[16px]" data-node-id="3092:25272" data-name="trailing-icon">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgTrailingIcon2} />
          </div>
        ))}
    </div>
  );
}
